const crypto = require('crypto');

const input = $input.first();
const headers = input.json.headers ?? {};
const signatureEntry = Object.entries(headers).find(([key]) => key.toLowerCase() === 'x-axur-signature');
const receivedSignature = String(signatureEntry?.[1] ?? '').trim().toLowerCase().replace(/^sha256=/, '');

let secret = '';
try {
  secret = String($vars.AXUR_WEBHOOK_SECRET ?? '').trim();
} catch {}
try {
  if (!secret) secret = String($env.AXUR_WEBHOOK_SECRET ?? '').trim();
} catch {}

if (!secret) {
  throw new Error('Configuração ausente: defina AXUR_WEBHOOK_SECRET nas variáveis do n8n.');
}
if (!/^[a-f0-9]{64}$/.test(receivedSignature)) {
  throw new Error('Requisição recusada: cabeçalho X-Axur-Signature ausente ou inválido.');
}

const binaryProperty = Object.keys(input.binary ?? {})[0];
let rawBody;
if (binaryProperty) {
  rawBody = await this.helpers.getBinaryDataBuffer(0, binaryProperty);
} else if (typeof input.json.rawBody === 'string') {
  rawBody = Buffer.from(input.json.rawBody, 'utf8');
} else {
  throw new Error('Não foi possível obter o corpo bruto. Habilite Raw Body no Webhook Axur.');
}

const expectedSignature = crypto.createHmac('sha256', secret).update(rawBody).digest('hex');
const receivedBuffer = Buffer.from(receivedSignature, 'hex');
const expectedBuffer = Buffer.from(expectedSignature, 'hex');
if (receivedBuffer.length !== expectedBuffer.length || !crypto.timingSafeEqual(receivedBuffer, expectedBuffer)) {
  throw new Error('Requisição recusada: assinatura Axur inválida.');
}

let payload;
try {
  payload = JSON.parse(rawBody.toString('utf8'));
} catch {
  throw new Error('Requisição recusada: o corpo recebido não é um JSON válido.');
}

const event = payload.event ?? {};
const eventType = String(event.type ?? 'evento.desconhecido');
if (eventType === 'ping') return [];

const ticket = payload.ticket ?? {};
const detections = Array.isArray(payload.detections) ? payload.detections : [];
const user = payload.user ?? {};
const dedupeKey = [eventType, event.sequence ?? event.date ?? '', ticket.key ?? '', detections[0]?.id ?? user.email ?? ''].join('|');
const state = $getWorkflowStaticData('global');
if (state.axurProcessedEvents?.[dedupeKey]) return [];

const eventLabels = {
  'ticket.created': 'Ticket criado',
  'ticket.reference.changed': 'Referência do ticket alterada',
  'ticket.detection.opened': 'Nova detecção aberta',
  'ticket.detection.reclassified': 'Detecção reclassificada',
  'ticket.detection.closed': 'Detecção encerrada',
  'ticket.quarantine.updated': 'Quarentena atualizada',
  'ticket.lifecycle.transition-applied': 'Ciclo de vida atualizado',
  'ticket.takedown.requested': 'Takedown solicitado',
  'ticket.takedown.notified': 'Takedown notificado',
  'ticket.takedown.verified': 'Takedown verificado',
  'ticket.takedown.done': 'Takedown concluído',
  'ticket.snapshot.added': 'Snapshot adicionado',
  'identity.session.refreshed': 'Sessão atualizada',
  'identity.session.created': 'Sessão criada',
  'identity.user.created': 'Usuário criado',
  'identity.user.deactivated': 'Usuário desativado',
  'identity.user.reactivated': 'Usuário reativado',
  'exposure.created': 'Nova exposição identificada',
  'exposure.updated': 'Exposição atualizada'
};

const eventDate = Number(event.date);
const formattedDate = Number.isFinite(eventDate)
  ? new Date(eventDate).toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' })
  : 'Não informada';
const customer = ticket.customer ?? detections[0]?.customer ?? user.customer;
const categories = [...new Set(detections.map((item) => item.category).filter(Boolean))];
const statuses = [...new Set(detections.map((item) => item.status).filter(Boolean))];
const assets = [...new Set(detections.flatMap((item) => Array.isArray(item.assets) ? item.assets : []).filter(Boolean))];

const lines = [
  '🔔 *Nova notificação da Axur*',
  '',
  `*Evento:* ${eventLabels[eventType] ?? eventType}`,
  `*Data:* ${formattedDate}`
];
if (customer) lines.push(`*Cliente:* ${customer}`);
if (ticket.key) lines.push(`*Ticket:* ${ticket.key}`);
if (ticket.type) lines.push(`*Tipo:* ${ticket.type}`);
if (ticket.status) lines.push(`*Status:* ${ticket.status}`);
if (ticket.reference) lines.push(`*Referência:* ${ticket.reference}`);
if (user.email) lines.push(`*Usuário:* ${[user.firstName, user.lastName].filter(Boolean).join(' ') || user.email} (${user.email})`);
if (detections.length) lines.push(`*Detecções:* ${detections.length}`);
if (categories.length) lines.push(`*Categorias:* ${categories.join(', ')}`);
if (statuses.length) lines.push(`*Situações:* ${statuses.join(', ')}`);
if (assets.length) lines.push(`*Ativos:* ${assets.join(', ')}`);
lines.push('', `_Código do evento: ${event.sequence ?? 'não informado'}_`);

return [{
  json: {
    dedupeKey,
    eventType,
    eventSequence: event.sequence ?? null,
    ticketKey: ticket.key ?? null,
    whatsappMessage: lines.join('\n').slice(0, 3500)
  }
}];

const source = $('Validar e preparar evento').first().json;
const state = $getWorkflowStaticData('global');
state.axurProcessedEvents ??= {};
state.axurProcessedEvents[source.dedupeKey] = new Date().toISOString();

const keys = Object.keys(state.axurProcessedEvents);
for (const key of keys.slice(0, Math.max(0, keys.length - 500))) {
  delete state.axurProcessedEvents[key];
}

return [];
